jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ── Audience gate ─────────────────────────────────────────────────
  var ALLOWED = {
    "andrew_nemiroff@colpal.com": 1,
    "jared_lerner@colpal.com": 1,
  };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "template_manager_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // ── Constants ─────────────────────────────────────────────────────
  var BD_TEMPLATES_DIR = "bd-templates";
  var MANIFEST_FILENAME = "bd-templates-manifest-v3.json";
  var MANIFEST_PATH = BD_TEMPLATES_DIR + "/" + MANIFEST_FILENAME;
  var SCHEMA_VERSION = 1;
  var BUS_TEMPLATE_PUSHED = "template_manager:pushed";

  // ── Small helpers ─────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _slug(s) {
    return String(s == null ? "" : s)
      .toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").replace(/_+/g, "_");
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }
  function _lsGet(k) { try { return localStorage.getItem(k); } catch (_e) { return null; } }
  function _getPat()    { return _lsGet("eli_user_github_pat"); }
  function _getRepo()   { return _lsGet("eli_github_repo"); }
  function _getBranch() { return _lsGet("eli_github_branch"); }

  // ── GitHub Contents API helpers (mirrors admin_library_publisher) ─
  function _strToB64(s) {
    var bytes = new TextEncoder().encode(s);
    var bin = "";
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }
  function _ghGet(pat, repo, branch, filePath) {
    var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
      "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
    return fetch(url, {
      cache: "no-store",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) return r.text().then(function (t) {
        throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200));
      });
      return r.json();
    });
  }
  function _ghPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
    var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
    var body = { message: message, content: _strToB64(contentStr), branch: branch };
    if (existingSha) body.sha = existingSha;
    function _doPut(attempt) {
      return fetch(url, {
        method: "PUT",
        headers: {
          "Authorization": "Bearer " + pat,
          "Accept": "application/vnd.github+json",
          "X-GitHub-Api-Version": "2022-11-28",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      }).then(function (r) {
        if (r.ok) return r.json();
        return r.text().then(function (t) {
          // Auto-retry on the rule-timeout 403 (matches admin_library_publisher).
          var isRuleTimeout = r.status === 403 && (
            /Restricts updates to workflow files/i.test(t) ||
            /Rule was unable to be completed/i.test(t)
          );
          if (isRuleTimeout && attempt < 3) {
            var delay = 1500 * Math.pow(2, attempt - 1);
            return new Promise(function (resolve) { setTimeout(resolve, delay); })
              .then(function () { return _doPut(attempt + 1); });
          }
          throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200));
        });
      });
    }
    return _doPut(1).then(function (result) {
      // Fire-and-forget jsdelivr cache purge — same pattern as admin_library_publisher.
      var purgeBranchUrl = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filePath;
      var purgeLatestUrl = "https://purge.jsdelivr.net/gh/" + repo + "/" + filePath;
      return Promise.all([
        fetch(purgeBranchUrl).catch(function () {}),
        fetch(purgeLatestUrl).catch(function () {}),
      ]).then(function () { return result; });
    });
  }

  // ── Storage helpers ──────────────────────────────────────────────
  function _loadAllTemplates() {
    return eli.storage.getAll("bd_templates").then(function (rows) {
      rows = (rows || []).filter(function (r) {
        return r && typeof r === "object" && r.id && String(r.id).charAt(0) !== "_";
      });
      rows.sort(function (a, b) {
        return String(a.name || a.id).localeCompare(String(b.name || b.id));
      });
      return rows;
    });
  }
  function _putTemplate(row) { return eli.storage.put("bd_templates", row); }

  // ── Manifest helpers ─────────────────────────────────────────────
  // Manifest shape: { schemaVersion, lastUpdated, templates: [...] }
  // Each entry: { id, name, agreementType, filename, size, lastUpdated,
  //               version, core, defaultForType, audienceEmails,
  //               audienceGroups, aliases }
  function _buildManifestEntry(row) {
    return {
      id: row.id,
      name: row.name || row.id,
      agreementType: row.agreementType || "",
      filename: row.id + ".json",
      size: (row.content || "").length,
      // Timestamp-based versioning — no numeric v1/v2. Consumers
      // compare their cached row's publishedAt against manifest's
      // lastUpdated for staleness detection. ISO 8601 sorts cleanly.
      lastUpdated: row.publishedAt || row.modifiedAt || new Date().toISOString(),
      core: !!row.core,
      defaultForType: !!row.defaultForType,
      audienceEmails: row.audienceEmails || [],
      audienceGroups: row.audienceGroups || [],
      aliases: row.aliases || [],
    };
  }
  function _fetchRemoteManifest(pat, repo, branch) {
    return _ghGet(pat, repo, branch, MANIFEST_PATH).then(function (existing) {
      if (!existing) return { manifest: { schemaVersion: SCHEMA_VERSION, lastUpdated: null, templates: [] }, sha: null };
      var b64 = String(existing.content || "").replace(/\s/g, "");
      if (!b64) return { manifest: { schemaVersion: SCHEMA_VERSION, lastUpdated: null, templates: [] }, sha: existing.sha };
      var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
      var str = new TextDecoder().decode(bytes);
      try {
        var parsed = JSON.parse(str);
        return { manifest: parsed, sha: existing.sha };
      } catch (_e) {
        return { manifest: { schemaVersion: SCHEMA_VERSION, lastUpdated: null, templates: [] }, sha: existing.sha };
      }
    });
  }
  // Upsert a single template entry into the manifest, preserving all
  // other entries. Atomic-ish: pull remote, merge, push back with the
  // remote's sha (rejects on concurrent edit so we retry once with
  // fresh sha to avoid wiping a co-admin's push).
  function _upsertManifestEntry(pat, repo, branch, entry) {
    // 2026-05-22 v2: bumped retry budget from 1 to 4 with exponential
    // backoff (250ms, 500ms, 1s, 2s). Back-to-back template pushes
    // were hitting sha conflicts in the manifest write step — the
    // single retry sometimes wasn't enough when GitHub's index hadn't
    // settled between the per-file PUT and the manifest PUT. With 4
    // retries + backoff, the manifest upsert essentially can't lose
    // a push to a transient sha mismatch.
    function _attempt(attemptNum) {
      return _fetchRemoteManifest(pat, repo, branch).then(function (state) {
        var manifest = state.manifest;
        var idx = (manifest.templates || []).findIndex(function (t) { return t.id === entry.id; });
        if (idx >= 0) manifest.templates[idx] = entry;
        else (manifest.templates = manifest.templates || []).push(entry);
        manifest.schemaVersion = SCHEMA_VERSION;
        manifest.lastUpdated = new Date().toISOString();
        manifest.templates.sort(function (a, b) {
          return String(a.name || a.id).localeCompare(String(b.name || b.id));
        });
        return _ghPut(pat, repo, branch, MANIFEST_PATH,
          JSON.stringify(manifest, null, 2),
          "template_manager: upsert " + entry.id + " @ " + entry.lastUpdated,
          state.sha
        ).catch(function (e) {
          var isShaConflict = /HTTP 409|HTTP 422|sha does not match|does not match the expected/i.test(String(e && e.message));
          if (isShaConflict && attemptNum < 4) {
            var delay = 250 * Math.pow(2, attemptNum - 1);
            eli.log.event("tool", "template_manager_manifest_retry", {
              entryId: entry.id, attempt: attemptNum, delay: delay, reason: "sha_conflict",
            });
            return new Promise(function (resolve) { setTimeout(resolve, delay); })
              .then(function () { return _attempt(attemptNum + 1); });
          }
          throw e;
        }).then(function (putResult) {
          // 2026-05-22 v3: POST-WRITE VERIFICATION.
          // GitHub Contents API has eventual consistency between
          // reads and writes — a fresh GET can return stale SHA
          // briefly after a previous PUT, letting our PUT succeed
          // (no 409!) while actually overwriting a concurrent
          // change. Sha-conflict retry doesn't catch this.
          //
          // Defense: after PUT returns 200, GET the manifest back
          // and verify our entry is there with the right timestamp.
          // If not, the write silently lost — retry the whole thing.
          // Wait 800ms before verifying so GitHub's index has time
          // to catch up (faster than that, the verify GET itself
          // can return stale data and false-positive a retry).
          return new Promise(function (resolve) { setTimeout(resolve, 800); })
            .then(function () { return _fetchRemoteManifest(pat, repo, branch); })
            .then(function (verifyState) {
              var found = (verifyState.manifest.templates || []).find(function (t) {
                return t.id === entry.id;
              });
              var landed = found && found.lastUpdated === entry.lastUpdated;
              if (landed) {
                return putResult; // confirmed — write was real
              }
              // Not reflected — silent overwrite happened.
              if (attemptNum < 4) {
                var delay = 500 * Math.pow(2, attemptNum - 1); // 500ms, 1s, 2s, 4s
                eli.log.event("tool", "template_manager_manifest_retry", {
                  entryId: entry.id, attempt: attemptNum, delay: delay,
                  reason: "verify_failed",
                  expected: entry.lastUpdated,
                  actualEntry: found ? found.lastUpdated : "missing",
                });
                return new Promise(function (resolve) { setTimeout(resolve, delay); })
                  .then(function () { return _attempt(attemptNum + 1); });
              }
              throw new Error("Manifest entry for " + entry.id + " did not land after 4 attempts — last verify saw " +
                (found ? "stale timestamp " + found.lastUpdated : "missing entry"));
            });
        });
      });
    }
    return _attempt(1);
  }
  function _removeManifestEntry(pat, repo, branch, id) {
    function _attempt(retry) {
      return _fetchRemoteManifest(pat, repo, branch).then(function (state) {
        var manifest = state.manifest;
        var before = (manifest.templates || []).length;
        manifest.templates = (manifest.templates || []).filter(function (t) { return t.id !== id; });
        if (manifest.templates.length === before) return null; // wasn't there
        manifest.schemaVersion = SCHEMA_VERSION;
        manifest.lastUpdated = new Date().toISOString();
        return _ghPut(pat, repo, branch, MANIFEST_PATH,
          JSON.stringify(manifest, null, 2),
          "template_manager: remove " + id, state.sha
        ).catch(function (e) {
          if (!retry && /HTTP 409|sha does not match/i.test(String(e && e.message))) return _attempt(true);
          throw e;
        });
      });
    }
    return _attempt(false);
  }

  // ── Per-template publish ─────────────────────────────────────────
  // Atomic order:
  //   1. PUT bd-templates/<id>.json (the content)
  //   2. PUT bd-templates/<manifest> (registers the new content)
  //   3. Mark local row published
  // CDN-first, manifest-last — readers never get 404 because manifest
  // points at a file that doesn't exist yet.
  function _publishTemplate(row, opts) {
    opts = opts || {};
    var pat = _getPat(); var repo = _getRepo(); var branch = _getBranch();
    if (!pat || !repo || !branch) {
      return Promise.reject(new Error("GitHub credentials missing. Open Admin Library Publisher → import credentials first."));
    }
    if (!row || !row.id || !row.content) {
      return Promise.reject(new Error("Template missing id or content."));
    }
    var fileName = row.id + ".json";
    var filePath = BD_TEMPLATES_DIR + "/" + fileName;
    var publishTimestamp = new Date().toISOString();
    // Wrap the content in a small published envelope so the consumer
    // gets metadata alongside the raw content string. No numeric
    // version — publishedAt timestamp is the canonical "which build"
    // identifier. Consumers compare timestamps to detect staleness.
    var payload = {
      id: row.id,
      name: row.name || row.id,
      agreementType: row.agreementType || "",
      party: row.party || "",
      content: row.content,
      publishedAt: publishTimestamp,
      publishedBy: userEmail,
      core: !!row.core,
      defaultForType: !!row.defaultForType,
      audienceEmails: row.audienceEmails || [],
      audienceGroups: row.audienceGroups || [],
      aliases: row.aliases || [],
    };
    var payloadStr = JSON.stringify(payload);
    // Step 1: get existing sha if file exists (otherwise PUT 422s).
    return _ghGet(pat, repo, branch, filePath).then(function (existing) {
      var existingSha = existing ? existing.sha : null;
      // Commit message uses date stamp, not v-number. Easier to scan
      // git log for "what changed on May 22?" than for "v7 of what?".
      var commitMsg = "template_manager: publish " + row.id +
        " @ " + publishTimestamp.replace("T", " ").replace(/\..*/, "") +
        " (" + Math.round(payloadStr.length / 1024) + "KB)";
      // Step 2: PUT the content file.
      return _ghPut(pat, repo, branch, filePath, payloadStr, commitMsg, existingSha);
    }).then(function () {
      // Step 3: upsert manifest entry (atomic).
      var entryRow = Object.assign({}, row, { publishedAt: publishTimestamp });
      var entry = _buildManifestEntry(entryRow);
      entry.size = payloadStr.length;
      return _upsertManifestEntry(pat, repo, branch, entry);
    }).then(function () {
      // Step 4: write local row state (publishedAt only — no version bump).
      row.publishedAt = publishTimestamp;
      row.publishedSize = payloadStr.length;
      return _putTemplate(row);
    }).then(function () {
      // Notify other tools (Build Draft picker can refresh its manifest cache).
      try { eli.bus && eli.bus.emit && eli.bus.emit(BUS_TEMPLATE_PUSHED, { id: row.id, publishedAt: publishTimestamp }); } catch (_e) {}
      eli.log.event("tool", "template_manager_published", {
        id: row.id, publishedAt: publishTimestamp, size: payloadStr.length,
      });
      return { ok: true, publishedAt: publishTimestamp, size: payloadStr.length };
    });
  }

  // ── UI ───────────────────────────────────────────────────────────
  var _state = {
    templates: [],
    filter: "",
    typeFilter: "",
    coreOnly: false,
    unpubOnly: false,
    editId: null,
    pushQueue: null, // { items: [{id,status,error}], inFlight: id }
  };

  function _refresh() {
    return _loadAllTemplates().then(function (rows) {
      _state.templates = rows;
      _renderList();
    });
  }

  function _open() {
    _closeOverlay();
    var overlay = document.createElement("div");
    overlay.id = "_eli3_tm_overlay";
    overlay.style.cssText =
      "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,0.55);" +
      "display:flex;align-items:center;justify-content:center;z-index:9500;" +
      "font-family:Inter,system-ui,sans-serif;";
    var card = document.createElement("div");
    card.style.cssText =
      "background:#fff;width:94%;max-width:1180px;height:90vh;" +
      "border:1px solid #cbd5e1;border-radius:0;box-shadow:0 24px 60px rgba(15,23,42,0.45);" +
      "display:flex;flex-direction:column;overflow:hidden;";
    card.innerHTML =
      // Header — navy gradient + gold underline (kernel pattern).
      '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);padding:14px 22px;border-bottom:3px solid #c9a227;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font-size:10px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.22em;">Build Draft · Admin</div>' +
          '<div style="font-family:Georgia,serif;font-size:20px;font-weight:800;color:#fff;margin-top:3px;">📐 Template Manager</div>' +
        '</div>' +
        '<button id="_eli3_tm_close" style="background:transparent;border:none;color:#fef3c7;font-size:22px;cursor:pointer;line-height:1;">✕</button>' +
      '</div>' +
      // Stats bar.
      '<div id="_eli3_tm_stats" style="padding:10px 22px;background:linear-gradient(180deg,#f8fafc,#f1f5f9);border-bottom:1px solid #e2e8f0;display:flex;gap:14px;align-items:center;flex-wrap:wrap;"></div>' +
      // Filters bar.
      '<div id="_eli3_tm_filters" style="padding:8px 22px;background:#fff;border-bottom:1px solid #e2e8f0;display:flex;gap:8px;align-items:center;flex-wrap:wrap;"></div>' +
      // Body — list + edit panel.
      '<div style="flex:1;display:flex;min-height:0;background:#f8fafc;">' +
        '<div id="_eli3_tm_left" style="flex:1;min-width:0;display:flex;flex-direction:column;border-right:1px solid #e2e8f0;">' +
          '<div id="_eli3_tm_list" style="flex:1;overflow-y:auto;padding:10px 16px 16px;"></div>' +
        '</div>' +
        '<div id="_eli3_tm_right" style="width:46%;min-width:380px;display:flex;flex-direction:column;background:#fff;overflow-y:auto;"></div>' +
      '</div>' +
      // Progress overlay slot (visible during bulk push).
      '<div id="_eli3_tm_progress"></div>';
    overlay.appendChild(card);
    document.body.appendChild(overlay);
    document.getElementById("_eli3_tm_close").onclick = _closeOverlay;
    overlay.onclick = function (ev) { if (ev.target === overlay) _closeOverlay(); };
    _renderStats(); _renderFilters(); _renderEditPanel();
    _refresh();
  }
  function _closeOverlay() {
    var el = document.getElementById("_eli3_tm_overlay");
    if (el && el.parentNode) el.parentNode.removeChild(el);
  }

  function _renderStats() {
    var el = document.getElementById("_eli3_tm_stats");
    if (!el) return;
    var total = _state.templates.length;
    var published = _state.templates.filter(function (t) { return !!t.publishedAt; }).length;
    var unpublished = total - published;
    var totalSize = _state.templates.reduce(function (a, t) { return a + ((t.content || "").length); }, 0);
    var coreCount = _state.templates.filter(function (t) { return !!t.core; }).length;
    el.innerHTML =
      '<div style="font:700 12px Inter,sans-serif;color:#0f172a;">' +
        total + ' templates · ' + published + ' published · ' + unpublished + ' local-only · ' +
        '⭐ ' + coreCount + ' core · ' +
        Math.round(totalSize / 1024 / 1024 * 10) / 10 + ' MB total' +
      '</div>' +
      '<div style="margin-left:auto;display:flex;gap:6px;">' +
        '<button id="_eli3_tm_checknow" title="Manually trigger the template-manifest sync — pulls the manifest from CDN, compares to local IDB, downloads any missing core templates. Works without the kernel deploy (bypasses the bus event path)." style="padding:7px 12px;font-size:11px;font-weight:800;color:#1e3a8a;background:linear-gradient(180deg,#eff6ff,#dbeafe);border:1px solid #3b82f6;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">🔍 Check CDN Now</button>' +
        '<button id="_eli3_tm_markallcore" title="Flag every template currently in the list as ⭐ Core. Use once to bring legacy templates into the core-batch download tier; new templates default to lazy." style="padding:7px 12px;font-size:11px;font-weight:800;color:#7c2d12;background:linear-gradient(180deg,#fff7ed,#ffedd5);border:1px solid #ea580c;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">⭐ Mark All as Core</button>' +
        '<button id="_eli3_tm_pushall" title="Push every UNPUBLISHED template to the CDN, one at a time with retry. Per-template status shown in the progress overlay." style="padding:7px 12px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#16a34a,#15803d);border:1px solid #15803d;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">📤 Push All Pending</button>' +
        '<button id="_eli3_tm_refresh" title="Reload the templates list from local IDB." style="padding:7px 12px;font-size:11px;font-weight:800;color:#475569;background:linear-gradient(180deg,#f8fafc,#e2e8f0);border:1px solid #cbd5e1;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">🔄 Refresh</button>' +
      '</div>';
    document.getElementById("_eli3_tm_refresh").onclick = function () { _refresh(); _renderStats(); };
    document.getElementById("_eli3_tm_pushall").onclick = function () { _bulkPushUnpublished(); };
    document.getElementById("_eli3_tm_markallcore").onclick = function () { _markAllAsCore(); };
    document.getElementById("_eli3_tm_checknow").onclick = function () { _checkCdnNow(); };
  }

  // ── Manual template-manifest check (bypasses kernel bus event) ────
  // Calls build_draft's fetchManifest + compares to local rows + shows
  // a result toast. Works even when the kernel deploy hasn't shipped
  // the bus emit yet — useful for testing the consume side end-to-end.
  function _checkCdnNow() {
    var btn = document.getElementById("_eli3_tm_checknow");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Checking…"; }
    var hasFetch = !!(eli.get && typeof eli.get("build_draft", "fetchManifest") === "function");
    if (!hasFetch) {
      _toast("Build Draft needs update — fetchManifest dispatch missing.", "err");
      if (btn) { btn.disabled = false; btn.textContent = "🔍 Check CDN Now"; }
      return;
    }
    eli.dispatch("build_draft", "fetchManifest").then(function (manifest) {
      if (!manifest || !Array.isArray(manifest.templates)) {
        _toast("No template manifest on CDN yet — push at least one template first.", "info");
        return;
      }
      var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
      var me = String((ident && ident.email) || "").toLowerCase().trim();
      var visible = manifest.templates.filter(function (e) {
        if (!e.audienceEmails || !e.audienceEmails.length) return true;
        return e.audienceEmails.map(function (s) { return String(s || "").toLowerCase().trim(); }).indexOf(me) !== -1;
      });
      return eli.storage.getAll("bd_templates").then(function (localRows) {
        var localById = {};
        (localRows || []).forEach(function (r) { if (r && r.id) localById[r.id] = r; });
        var missing = [], updated = [];
        visible.forEach(function (e) {
          var have = localById[e.id];
          if (!have) { missing.push(e); return; }
          var rTs = e.lastUpdated ? new Date(e.lastUpdated).getTime() : 0;
          var lTs = have.publishedAt ? new Date(have.publishedAt).getTime() : 0;
          if (rTs > lTs) updated.push(e);
        });
        if (missing.length || updated.length) {
          var parts = [];
          if (missing.length) parts.push(missing.length + " new");
          if (updated.length) parts.push(updated.length + " updated");
          _toast("🆕 " + parts.join(" + ") + " template(s) on CDN. Open Build Draft to install (Turn 2 picker) or use eli.dispatch('build_draft','fetchTemplate', id) in console.", "info");
        } else {
          _toast("✅ All " + visible.length + " visible CDN templates already in local IDB.", "ok");
        }
      });
    }).catch(function (e) {
      _toast("Manifest fetch failed: " + (e && e.message), "err");
    }).then(function () {
      if (btn) { btn.disabled = false; btn.textContent = "🔍 Check CDN Now"; }
    });
  }

  // ── Bulk: mark every template in the list as Core ────────────────
  // One-shot helper for migrating an existing template library where
  // all current templates should be in the core-batch tier. Skips
  // already-core rows. Doesn't re-publish — just sets the flag so the
  // next push picks it up.
