        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Audience Groups <span style="color:#16a34a;font-weight:700;">' + (groupsStr ? "" : "(empty = no group restriction)") + '</span></label>' +
          '<input id="_eli3_tm_groups" type="text" value="' + _esc(groupsStr) + '" style="width:100%;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;box-sizing:border-box;">' +
          '<div style="font:500 10px Inter,sans-serif;color:#94a3b8;margin-top:3px;">Comma-separated group tags. Future: group system. Today: free-text tags for organization.</div>' +
        '</div>' +
        // Status / metadata — date-based identification, no v-numbers.
        '<div style="margin-top:14px;padding:10px 12px;background:#f1f5f9;border-left:3px solid #cbd5e1;font:500 11px/1.5 Inter,sans-serif;color:#475569;">' +
          '<div><b>ID:</b> <code style="background:#fff;padding:1px 4px;font-family:monospace;">' + _esc(t.id) + '</code></div>' +
          '<div><b>Content size:</b> ' + Math.round(((t.content || "").length) / 1024) + ' KB</div>' +
          '<div><b>✏️ Last edited:</b> ' + _esc(_absoluteDate(t.modifiedAt)) + ' <span style="color:#94a3b8;">(' + _relativeDate(t.modifiedAt) + ')</span></div>' +
          (t.publishedAt
            ? '<div><b>☁ Published to CDN:</b> ' + _esc(_absoluteDate(t.publishedAt)) + ' <span style="color:#94a3b8;">(' + _relativeDate(t.publishedAt) + ')</span></div>'
            : '<div style="color:#92400e;"><b>⚠️ Never published</b> — click Save + Push to publish to CDN.</div>') +
        '</div>' +
      '</div>' +
      // 2026-05-22 v2: simplified to a single "Push" button. Save is
      // implicit — every Push grabs current form values, writes to
      // local IDB, then uploads to CDN. No standalone Save (confusing
      // — created "edited since push" limbo) and no separate Save+Push
      // (redundant labeling — Push already means "publish current
      // state"). One label across the app: Push.
      '<div style="padding:12px 18px;border-top:1px solid #e2e8f0;background:#f8fafc;display:flex;gap:8px;justify-content:flex-end;">' +
        '<button id="_eli3_tm_cancel" style="padding:7px 14px;font-size:11px;font-weight:800;color:#475569;background:#fff;border:1px solid #cbd5e1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">Cancel</button>' +
        '<button id="_eli3_tm_save_push" title="Save your edits + push to CDN. The save step is implicit — clicking Push always saves form changes first." style="padding:8px 16px;font-size:11.5px;font-weight:800;color:#fff;background:linear-gradient(180deg,#16a34a,#15803d);border:1px solid #15803d;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">📤 Push</button>' +
      '</div>';
    document.getElementById("_eli3_tm_cancel").onclick = function () {
      _state.editId = null; _renderList(); _renderEditPanel();
    };
    document.getElementById("_eli3_tm_save_push").onclick = function () { _saveEdit(true); };
  }

  function _saveEdit(thenPush) {
    var t = _state.templates.find(function (r) { return r.id === _state.editId; });
    if (!t) return;
    t.name = document.getElementById("_eli3_tm_name").value.trim() || t.id;
    t.agreementType = document.getElementById("_eli3_tm_type_edit").value.trim();
    t.aliases = document.getElementById("_eli3_tm_aliases").value.split(",").map(function (s) { return s.trim(); }).filter(Boolean);
    t.core = document.getElementById("_eli3_tm_core").checked;
    t.defaultForType = document.getElementById("_eli3_tm_default").checked;
    t.audienceEmails = document.getElementById("_eli3_tm_emails").value.split(",").map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);
    t.audienceGroups = document.getElementById("_eli3_tm_groups").value.split(",").map(function (s) { return s.trim(); }).filter(Boolean);
    t.modifiedAt = new Date().toISOString();
    return _putTemplate(t).then(function () {
      // 2026-05-22: only toast on save-only path. When thenPush is
      // true, the subsequent _pushOne will toast on completion —
      // showing two toasts in rapid succession (Saved → Pushed) made
      // the first one feel "missing" because the kernel's toast
      // component dismissed it before the user registered it. One
      // toast at the end is cleaner UX.
      if (!thenPush) _toast("✅ Saved metadata.", "ok");
      if (thenPush) return _pushOne(t.id);
      return _refresh();
    }).catch(function (e) {
      _toast("Save failed: " + (e && e.message), "err");
    });
  }

  // ── Tile + dispatch entry ─────────────────────────────────────────
  eli.register({
    tile: { app_template_manager: _open },
    template_manager: {
      open: _open,
      publish: function (id) {
        return _loadAllTemplates().then(function (rows) {
          var t = rows.find(function (r) { return r.id === id; });
          if (!t) throw new Error("Template not found: " + id);
          return _publishTemplate(t);
        });
      },
    },
  });
  eli.log.event("tool", "template_manager_init", { email: userEmail });
}
